contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);
        uint preOwnerBalance = address(this).balance;
        uint preDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        address preOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint preContractBalance = address(c).balance;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        assert(
            c.owner() == preOwner &&
            c.depositsCount() == preDeposits &&
            address(c).balance == 0 &&
            address(this).balance == preOwnerBalance + preContractBalance
        );
    }

    receive() external payable {}
}

