    }

    function _run(uint256 amount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint preOwnerBalance = address(this).balance;
        uint256 preDeposits;
        try c.depositsCount() returns (uint256 __r) { preDeposits = __r; } catch { return; }
        address preOwner;
        try c.owner() returns (address __r) { preOwner = __r; } catch { return; }
        uint preContractBalance = address(c).balance;
        try c.withdrawAll() {} catch { return; }
        assertTrue(c.owner() == preOwner &&
            c.depositsCount() == preDeposits &&
            address(c).balance == 0 &&
            address(this).balance == preOwnerBalance + preContractBalance);
